<script setup lang="ts">
import{computed,onScopeDispose,ref}from'vue';import{RefreshCw}from'@lucide/vue';import{isApiError}from'../../../shared/api/errors';import{MomButton,MomSelect}from'../../../shared/ui';import MomManagementHeader from'../../../shared/components/MomManagementHeader.vue';import MomListSurface from'../../../shared/components/MomListSurface.vue';import MomDataTable,{type MomColumn}from'../../../shared/components/MomDataTable.vue';import PageContainer from'../../../shared/components/PageContainer.vue';import{useLocale}from'../../../shared/i18n/locale';import{runConsistencyCheck,type GovernanceIssue,type GovernanceReport,type GovernanceScope}from'../api/governance-api';import'./mdm-pages.css';
const{t}=useLocale();const scope=ref<GovernanceScope>('ALL'),report=ref<GovernanceReport>(),loading=ref(false),error=ref('');let controller:AbortController|undefined,requestNo=0,disposed=false;
const scopes=computed(()=>[{value:'ALL',label:t('mdm.governance.all')},{value:'ORGANIZATION',label:t('mdm.governance.organization')},{value:'WAREHOUSE',label:t('mdm.governance.warehouse')},{value:'MATERIAL_UOM',label:t('mdm.governance.materialUom')},{value:'MANUFACTURING_DEFINITION',label:t('mdm.governance.manufacturing')}]);
const columns=computed<MomColumn[]>(()=>[{key:'issueType',title:t('mdm.governance.issueType'),minWidth:170},{key:'resourceType',title:t('mdm.governance.resource'),minWidth:180},{key:'businessCode',title:t('mdm.governance.businessCode'),minWidth:150},{key:'severity',title:t('mdm.governance.severity'),width:110},{key:'reasonCode',title:t('mdm.governance.reason'),minWidth:260}]);
async function run():Promise<void>{const current=++requestNo;controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const value=await runConsistencyCheck(scope.value,controller.signal);if(!disposed&&current===requestNo)report.value=value;}catch(value){if(!disposed&&current===requestNo)error.value=isApiError(value)&&value.kind==='forbidden'?t('mdm.struct.forbidden'):t('mdm.struct.loadFailed');}finally{if(current===requestNo)loading.value=false;}}
function rowKey(row:GovernanceIssue):string{return`${row.resourceType}:${row.resourceId}:${row.reasonCode}`;}onScopeDispose(()=>{disposed=true;++requestNo;controller?.abort();});
</script>
<template><PageContainer><section class="mdm-plants" aria-labelledby="mdm-governance-title"><MomManagementHeader title-id="mdm-governance-title" :title="t('mdm.governance.title')" :description="t('mdm.governance.description')"><template #actions><label><span class="sr-only">{{t('mdm.governance.scope')}}</span><MomSelect v-model="scope" :options="scopes"/></label><MomButton :disabled="loading" @click="run"><RefreshCw :size="16"/>{{t('mdm.governance.run')}}</MomButton></template></MomManagementHeader>
<div v-if="error" class="mdm-plants__error" role="alert">{{error}} <MomButton variant="outline" @click="run">{{t('mdm.struct.retry')}}</MomButton></div><template v-else-if="report"><p role="status">{{t('mdm.governance.checkedAt')}}: {{new Date(report.checkedAt).toLocaleString()}} · {{report.issueCount}}</p><p v-if="report.truncated" class="mdm-plants__error" role="alert">{{t('mdm.governance.truncated')}}</p><MomListSurface :title="t('mdm.governance.title')" :hint="t('mdm.governance.description')" :loading="loading" :loading-text="t('mdm.struct.loading')"><MomDataTable :rows="report.issues.map(row=>({...row,id:rowKey(row)}))" :columns="columns" :empty-text="t('mdm.governance.noIssues')"/></MomListSurface></template><MomListSurface v-else :title="t('mdm.governance.title')" :hint="t('mdm.governance.description')" :loading="loading" :loading-text="t('mdm.struct.loading')"><p>{{t('mdm.governance.run')}}</p></MomListSurface>
</section></PageContainer></template>
